package vn.aicrm.retail;

import java.util.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.math.BigDecimal;
import java.util.zip.*;
import javax.xml.parsers.DocumentBuilderFactory;
import org.w3c.dom.*;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.*;
import org.springframework.stereotype.Service;
import org.springframework.security.core.Authentication;
import static vn.aicrm.retail.RetailAccess.*;

/** Excel/CSV preview is persisted; commit is atomic and opening stock/debt still requires a second approver. */
@Service
public class RetailImport {
  private final RetailAccess r;private final RetailPartners partners;private final RetailCatalog catalog;private final RetailDocuments documents;
  public RetailImport(RetailAccess r,RetailCatalog catalog,RetailDocuments documents,RetailPartners partners){this.r=r;this.partners=partners;this.catalog=catalog;this.documents=documents;}
  public Object preview(Authentication a,JsonNode x){
    r.require(a,"SETUP");var t=r.tenant(a);String kind=required(x,"kind",30);if(!Set.of("SKUS","PARTNERS","OPENING_STOCK","OPENING_DEBT").contains(kind))throw problem("IMPORT_KIND","Loại dữ liệu không hợp lệ");var wh=r.warehouse(a,uuid(x,"warehouseId"));var input=x.path("rows");if(!input.isArray()||input.isEmpty()||input.size()>500)throw problem("IMPORT_SIZE","Mỗi batch cần 1–500 dòng");var checksum=RetailCommands.hash(kind+input.toString());var old=r.db.queryForList("select * from retail.import_batch where tenant_id=? and kind=? and checksum=?",t,kind,checksum);if(!old.isEmpty()){var existing=old.getFirst();r.warehouse(a,(UUID)existing.get("warehouse_id"));return r.clean(existing);}
    var errors=r.json.createArrayNode();var seen=new HashSet<String>();int row=1;
    for(var item:input){row++;try{
      if(kind.equals("PARTNERS")){String code=required(item,"code",60);if(!seen.add(code))throw problem("IMPORT_DUPLICATE","Trùng mã trong file");partners.importPartner(a,item,true);}else if(kind.equals("SKUS")){String code=required(item,"code",60);required(item,"name",160);if(!seen.add(code))throw problem("IMPORT_DUPLICATE","Trùng mã trong file");String table=kind.equals("SKUS")?"sku":"partner";if(r.db.queryForObject("select count(*) from retail."+table+" where tenant_id=? and code=?",Integer.class,t,code)>0)throw problem("IMPORT_DUPLICATE","Mã đã có trong hệ thống");if(kind.equals("SKUS")){required(item,"unit",40);if(num(item,"price",BigDecimal.ZERO).signum()<0)throw problem("INVALID_PRICE","Giá không âm");}else if(!Set.of("CUSTOMER","SUPPLIER","COLLABORATOR").contains(text(item,"kind","CUSTOMER")))throw problem("INVALID_PARTNER","Loại đối tác không hợp lệ");}
      else if(kind.equals("OPENING_STOCK")){required(item,"skuCode",60);positive(item,"qty");if(num(item,"price",BigDecimal.ZERO).signum()<0)throw problem("INVALID_PRICE","Giá vốn không âm");if(r.db.queryForObject("select count(*) from retail.sku where tenant_id=? and code=?",Integer.class,t,text(item,"skuCode",""))==0)throw problem("SKU_NOT_FOUND","SKU chưa có; nhập hàng hóa trước");}
      else{required(item,"partnerCode",60);if(!Set.of("AR","AP").contains(text(item,"kind","")))throw problem("DEBT_KIND","kind phải AR hoặc AP");if(num(item,"amount",BigDecimal.ZERO).signum()<=0)throw problem("INVALID_AMOUNT","Công nợ đầu kỳ phải dương");if(r.db.queryForObject("select count(*) from retail.partner where tenant_id=? and code=?",Integer.class,t,text(item,"partnerCode",""))==0)throw problem("PARTNER_NOT_FOUND","Đối tác chưa có; nhập đối tác trước");}
    }catch(Exception e){errors.addObject().put("row",row).put("message",e.getMessage());}}
    UUID id=UUID.randomUUID();r.db.update("insert into retail.import_batch(id,tenant_id,branch_id,warehouse_id,kind,checksum,rows,errors,creator_id) values(?,?,?,?,?,?,?::jsonb,?::jsonb,?)",id,t,wh.get("branch_id"),wh.get("id"),kind,checksum,input.toString(),errors.toString(),r.actor(a));return r.clean(r.one("import_batch",t,id));
  }
  public Object commit(Authentication a,UUID id){r.require(a,"SETUP");var t=r.tenant(a);var batch=r.one("import_batch",t,id);r.warehouse(a,(UUID)batch.get("warehouse_id"));if(!"PREVIEW".equals(batch.get("status")))throw problem("IMPORT_ALREADY_COMMITTED","Batch đã được xác nhận");if(!r.node(batch.get("errors")).isEmpty())throw problem("IMPORT_ERRORS","Sửa các dòng lỗi trước khi nhập");String kind=batch.get("kind").toString();var created=r.json.createArrayNode();var rows=r.node(batch.get("rows"));
    if(kind.equals("SKUS")||kind.equals("PARTNERS"))for(var row:rows)created.add(r.json.valueToTree(kind.equals("PARTNERS")?partners.importPartner(a,row,false):catalog.create(a,"skus",row)));
    else if(kind.equals("OPENING_STOCK")){ObjectNode d=r.json.createObjectNode().put("type","OPENING_STOCK").put("warehouseId",batch.get("warehouse_id").toString()).put("note","Tồn đầu kỳ từ batch "+id);var ls=d.putArray("lines");for(var row:rows){ObjectNode line=(ObjectNode)row.deepCopy();var sku=r.db.queryForObject("select id from retail.sku where tenant_id=? and code=?",UUID.class,t,text(row,"skuCode",""));line.put("skuId",sku.toString());ls.add(line);}created.add(r.json.valueToTree(documents.create(a,d)));}
    else for(var row:rows){var p=r.db.queryForObject("select id from retail.partner where tenant_id=? and code=?",UUID.class,t,text(row,"partnerCode",""));ObjectNode d=r.json.createObjectNode().put("type",text(row,"kind","").equals("AR")?"OPENING_AR":"OPENING_AP").put("partnerId",p.toString()).put("warehouseId",batch.get("warehouse_id").toString()).put("amount",num(row,"amount",BigDecimal.ZERO)).put("note","Công nợ đầu kỳ từ batch "+id);created.add(r.json.valueToTree(documents.create(a,d)));}
    r.db.update("update retail.import_batch set status='COMMITTED' where tenant_id=? and id=?",t,id);return Map.of("id",id,"created",created);
  }
  public JsonNode parse(byte[] bytes,String filename){if(bytes.length>2_000_000)throw problem("IMPORT_SIZE","File tối đa 2 MB");try{List<List<String>> cells=filename.toLowerCase().endsWith(".xlsx")?xlsx(bytes):csv(new String(bytes,StandardCharsets.UTF_8));if(cells.size()<2)throw problem("IMPORT_EMPTY","File cần header và dữ liệu");var rows=r.json.createArrayNode();var headers=cells.getFirst();if(new HashSet<>(headers).size()!=headers.size())throw problem("IMPORT_HEADER","Header bị trùng");for(int i=1;i<cells.size();i++){var row=cells.get(i);if(row.stream().allMatch(String::isBlank))continue;var obj=rows.addObject();for(int c=0;c<headers.size();c++){String key=headers.get(c).replace("\ufeff","").trim(),value=c<row.size()?row.get(c).trim():"";if(key.equals("serials")){var array=obj.putArray(key);if(!value.isBlank())for(var sn:value.split("\\|"))array.add(sn.trim());}else if(Set.of("allowOpened","stackable").contains(key))obj.put(key,value.equalsIgnoreCase("true")||value.equals("1"));else if(key.equals("units"))obj.set(key,value.isBlank()?r.json.createObjectNode():r.json.readTree(value));else obj.put(key,value);}}if(rows.size()>500)throw problem("IMPORT_SIZE","Tối đa 500 dòng mỗi lần");return rows;}catch(vn.coreplatform.shared.ApiExceptionHandler.ApiProblem p){throw p;}catch(Exception e){throw problem("IMPORT_FILE","Không đọc được file CSV UTF-8 hoặc Excel .xlsx hợp lệ");}}
  private List<List<String>> csv(String text){var rows=new ArrayList<List<String>>();var row=new ArrayList<String>();var cell=new StringBuilder();boolean quote=false;for(int i=0;i<text.length();i++){char c=text.charAt(i);if(c=='"'){if(quote&&i+1<text.length()&&text.charAt(i+1)=='"'){cell.append('"');i++;}else quote=!quote;}else if(c==','&&!quote){row.add(cell.toString());cell.setLength(0);}else if(c=='\n'&&!quote){row.add(cell.toString().replaceAll("\r$",""));rows.add(row);row=new ArrayList<>();cell.setLength(0);}else cell.append(c);}if(quote)throw problem("IMPORT_CSV","Dấu nháy CSV chưa đóng");if(!cell.isEmpty()||!row.isEmpty()){row.add(cell.toString());rows.add(row);}return rows;}
  private List<List<String>> xlsx(byte[] bytes)throws Exception{
    Map<String,byte[]> parts=new HashMap<>();int total=0;try(var zip=new ZipInputStream(new ByteArrayInputStream(bytes))){ZipEntry entry;while((entry=zip.getNextEntry())!=null){byte[] content=zip.readNBytes(5_000_001);total+=content.length;if(content.length>5_000_000||total>15_000_000)throw problem("IMPORT_SIZE","Excel giải nén vượt giới hạn");if(entry.getName().equals("xl/sharedStrings.xml")||entry.getName().equals("xl/worksheets/sheet1.xml"))parts.put(entry.getName(),content);}}
    var strings=new ArrayList<String>();if(parts.containsKey("xl/sharedStrings.xml")){var sis=xml(parts.get("xl/sharedStrings.xml")).getElementsByTagName("si");for(int i=0;i<sis.getLength();i++)strings.add(sis.item(i).getTextContent());}
    if(!parts.containsKey("xl/worksheets/sheet1.xml"))throw problem("IMPORT_SHEET","Cần dữ liệu ở sheet đầu tiên");var nodes=xml(parts.get("xl/worksheets/sheet1.xml")).getElementsByTagName("row");var rows=new ArrayList<List<String>>();for(int i=0;i<nodes.getLength();i++){Element row=(Element)nodes.item(i);var cells=row.getElementsByTagName("c");var out=new ArrayList<String>();for(int j=0;j<cells.getLength();j++){Element cell=(Element)cells.item(j);if(cell.getElementsByTagName("f").getLength()>0)throw problem("IMPORT_FORMULA","Chuyển công thức thành giá trị trước khi nhập");String ref=cell.getAttribute("r").replaceAll("[0-9]","");int col=0;for(char ch:ref.toCharArray())col=col*26+ch-'A'+1;if(col<=0||col>60)throw problem("IMPORT_COLUMNS","Tối đa 60 cột");while(out.size()<col)out.add("");var value=cell.getElementsByTagName(cell.getAttribute("t").equals("inlineStr")?"t":"v");String v=value.getLength()==0?"":value.item(0).getTextContent();if(cell.getAttribute("t").equals("s"))v=strings.get(Integer.parseInt(v));out.set(col-1,v);}rows.add(out);}return rows;
  }
  private Document xml(byte[] bytes)throws Exception{var f=DocumentBuilderFactory.newInstance();f.setFeature("http://apache.org/xml/features/disallow-doctype-decl",true);f.setFeature("http://xml.org/sax/features/external-general-entities",false);f.setFeature("http://xml.org/sax/features/external-parameter-entities",false);f.setXIncludeAware(false);f.setExpandEntityReferences(false);return f.newDocumentBuilder().parse(new ByteArrayInputStream(bytes));}
}
